import sys
import ast
import dis
import linecache
import os

CSE_FILE = os.path.abspath('/testbed/sympy/simplify/cse_main.py')

tracked_vars = {
    '_', 'arg', 'args', 'c', 'e', 'excluded_symbols', 'expr', 'exprs',
    'ign', 'ignore', 'nc', 'new_args', 'new_expr', 'opt_subs', 'order',
    'orig_expr', 'reduced_e', 'reduced_exprs', 'replacements', 'seen_subexp',
    'subs', 'sym', 'symbols', 'to_eliminate'
}

# Target function names (tree_cse and its inner functions)
TARGET_FUNCS = {'tree_cse', '_find_repeated', '_rebuild'}

# Function parameters
FUNC_PARAMS = {
    'tree_cse': {'exprs', 'symbols', 'opt_subs', 'order', 'ignore'},
    '_find_repeated': {'expr'},
    '_rebuild': {'expr'},
}

def get_line_source(filename, lineno):
    return linecache.getline(filename, lineno)

def get_reads_from_line(source_line):
    """Get variable names that are read (Load context) in a source line."""
    source_line = source_line.strip()
    if not source_line or source_line.startswith('#'):
        return set()
    reads = set()
    try:
        tree = ast.parse(source_line, mode='exec')
    except SyntaxError:
        try:
            tree = ast.parse(source_line, mode='eval')
        except SyntaxError:
            return set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            reads.add(node.id)
    return reads


def build_line_stores(code_obj):
    """Build a mapping from line number to set of variables stored on that line."""
    line_stores = {}
    current_line = None
    for instr in dis.get_instructions(code_obj):
        if instr.starts_line is not None:
            current_line = instr.starts_line
        if instr.opname in ('STORE_FAST', 'STORE_NAME', 'STORE_DEREF', 'STORE_GLOBAL'):
            if current_line is not None:
                if current_line not in line_stores:
                    line_stores[current_line] = set()
                line_stores[current_line].add(instr.argval)
    return line_stores


# Build line_stores lazily
_line_stores_cache = {}

def get_line_stores_for_code(code_obj):
    key = id(code_obj)
    if key not in _line_stores_cache:
        _line_stores_cache[key] = build_line_stores(code_obj)
    return _line_stores_cache[key]


class FuncTracer:
    def __init__(self):
        self.def_use_pairs = set()
        self.active_frames = {}  # frame_id -> state

    def trace_calls(self, frame, event, arg):
        if event == 'call':
            if (frame.f_code.co_filename == CSE_FILE and
                    frame.f_code.co_name in TARGET_FUNCS):
                frame_id = id(frame)
                func_name = frame.f_code.co_name
                func_def_line = frame.f_code.co_firstlineno

                # Initialize current_defs with function parameters
                params = FUNC_PARAMS.get(func_name, set())
                initial_defs = {}
                for var in params & tracked_vars:
                    if var in frame.f_locals:
                        initial_defs[var] = func_def_line

                # For inner functions, inherit defs from the parent call chain
                # by looking at outer frames
                # We need to pass in defs from the outer scope for closure vars
                parent_defs = self._get_parent_defs(frame)
                # Merge parent defs (but don't override local params)
                merged_defs = dict(parent_defs)
                merged_defs.update(initial_defs)

                self.active_frames[frame_id] = {
                    'prev_lineno': None,
                    'current_defs': merged_defs,
                    'func_name': func_name,
                    'code_obj': frame.f_code,
                }
                return self.make_line_tracer(frame_id)
        return None

    def _get_parent_defs(self, frame):
        """Get current_defs from parent tree_cse frame if it exists."""
        parent = frame.f_back
        while parent is not None:
            if (parent.f_code.co_filename == CSE_FILE and
                    parent.f_code.co_name in TARGET_FUNCS):
                parent_frame_id = id(parent)
                parent_state = self.active_frames.get(parent_frame_id)
                if parent_state is not None:
                    return dict(parent_state['current_defs'])
            parent = parent.f_back
        return {}

    def make_line_tracer(self, frame_id):
        def line_tracer(frame, event, arg):
            if event == 'line':
                self.on_line(frame, frame_id)
            elif event == 'return':
                self.on_return(frame, frame_id)
            return line_tracer
        return line_tracer

    def on_line(self, frame, frame_id):
        state = self.active_frames.get(frame_id)
        if state is None:
            return

        lineno = frame.f_lineno
        current_defs = state['current_defs']
        prev_lineno = state['prev_lineno']
        code_obj = state['code_obj']

        # Process defs from prev_lineno using bytecode analysis
        if prev_lineno is not None:
            line_stores = get_line_stores_for_code(code_obj)
            stored_vars = line_stores.get(prev_lineno, set())
            for var in stored_vars & tracked_vars:
                current_defs[var] = prev_lineno

        # Detect uses from current line (lineno): read the source
        src_line = get_line_source(CSE_FILE, lineno)
        reads = get_reads_from_line(src_line)
        for var in reads & tracked_vars:
            if var in current_defs:
                self.def_use_pairs.add((var, current_defs[var], lineno))

        # Update state
        state['prev_lineno'] = lineno

    def on_return(self, frame, frame_id):
        """Handle return event - process last line's defs and clean up."""
        state = self.active_frames.get(frame_id)
        if state is None:
            return
        # Process defs from the last executed line before return
        # (for the case when return happens after a def)
        lineno = frame.f_lineno
        current_defs = state['current_defs']
        prev_lineno = state['prev_lineno']
        code_obj = state['code_obj']

        if prev_lineno is not None:
            line_stores = get_line_stores_for_code(code_obj)
            stored_vars = line_stores.get(prev_lineno, set())
            for var in stored_vars & tracked_vars:
                current_defs[var] = prev_lineno

        del self.active_frames[frame_id]


tracer = FuncTracer()

def main_trace(frame, event, arg):
    return tracer.trace_calls(frame, event, arg)

