"""
Instrumentation to track def-use pairs for factorint function.
Uses bytecode analysis for detecting both defs (stores) and uses (loads).
"""
import sys
import dis
import os

FACTOR_FILE = os.path.abspath('/testbed/sympy/ntheory/factor_.py')

tracked_vars = frozenset({
    'B1', 'B2', '_', '_limit', 'a', 'a2', 'args', 'b', 'b2', 'c', 'd', 'e',
    'fac', 'facs', 'factor', 'factordict', 'factorlist', 'factors', 'fail_max',
    'fermat', 'found_trial', 'high', 'high_', 'i', 'iteration', 'k', 'key',
    'limit', 'low', 'm', 'multiple', 'n', 'next_p', 'num_curves', 'p', 'ps',
    'q', 'r', 'small', 'sn', 'sqrt_n', 'use_ecm', 'use_pm1', 'use_rho',
    'use_trial', 'v', 'verbose', 'visual', 'x'
})

# Function parameters - defined at the function definition line
FUNC_PARAMS = frozenset({'n', 'limit', 'use_trial', 'use_rho', 'use_pm1', 'use_ecm', 'verbose', 'visual', 'multiple'})

# Build bytecode-based line -> stores/loads maps
from sympy.ntheory.factor_ import factorint as _factorint
code = _factorint.__code__
line_stores_map = {}
line_loads_map = {}
current_line = None
for instr in dis.get_instructions(code):
    if instr.starts_line is not None:
        current_line = instr.starts_line
    if current_line is None:
        continue
    if instr.opname in ('STORE_FAST', 'STORE_NAME', 'STORE_DEREF', 'STORE_GLOBAL'):
        if instr.argval in tracked_vars:
            line_stores_map.setdefault(current_line, set()).add(instr.argval)
    elif instr.opname in ('LOAD_FAST', 'LOAD_NAME', 'LOAD_DEREF', 'LOAD_GLOBAL'):
        if instr.argval in tracked_vars:
            line_loads_map.setdefault(current_line, set()).add(instr.argval)

FUNC_DEF_LINE = code.co_firstlineno  # 1220


class FuncTracer:
    def __init__(self):
        self.def_use_pairs = set()
        self.active_frames = {}  # frame_id -> state

    def trace_calls(self, frame, event, arg):
        if event == 'call':
            if (frame.f_code.co_filename == FACTOR_FILE and
                    frame.f_code.co_name == 'factorint'):
                frame_id = id(frame)
                # Initialize current_defs with function parameters at FUNC_DEF_LINE
                initial_defs = {var: FUNC_DEF_LINE for var in FUNC_PARAMS & tracked_vars}
                self.active_frames[frame_id] = {
                    'prev_lineno': None,
                    'current_defs': initial_defs,
                }
                return self.make_line_tracer(frame_id)
        return None

    def make_line_tracer(self, frame_id):
        def line_tracer(frame, event, arg):
            if event == 'line':
                self.on_line(frame, frame_id)
            elif event == 'return':
                self.on_return(frame, frame_id)
            return line_tracer
        return line_tracer

    def on_line(self, frame, frame_id):
        state = self.active_frames.get(frame_id)
        if state is None:
            return

        lineno = frame.f_lineno
        current_defs = state['current_defs']
        prev_lineno = state['prev_lineno']

        # Step 1: Process stores from prev_lineno → update current defs
        if prev_lineno is not None:
            for var in line_stores_map.get(prev_lineno, set()):
                current_defs[var] = prev_lineno

        # Step 2: Record uses for the current line (before it executes)
        # For a line that both loads and stores the same var (e.g., n += 1),
        # the load happens before the store, so we record the use against the
        # current def (which will be updated when the NEXT line fires).
        for var in line_loads_map.get(lineno, set()):
            if var in current_defs:
                self.def_use_pairs.add((var, current_defs[var], lineno))

        # Step 3: Update state
        state['prev_lineno'] = lineno

    def on_return(self, frame, frame_id):
        """Handle return event."""
        state = self.active_frames.get(frame_id)
        if state is None:
            return
        # Process stores from the last executed line
        prev_lineno = state['prev_lineno']
        if prev_lineno is not None:
            current_defs = state['current_defs']
            for var in line_stores_map.get(prev_lineno, set()):
                current_defs[var] = prev_lineno
        del self.active_frames[frame_id]


tracer = FuncTracer()

def main_trace(frame, event, arg):
    return tracer.trace_calls(frame, event, arg)

# Run the test
sys.settrace(main_trace)

